"""Build the static research presentation from the retained release assets."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parents[1]
REPO = "https://github.com/joelcerraga/Kalshi-Mispricing-Arbitrage"
BASE = "https://joelcerraga.github.io/Kalshi-Mispricing-Arbitrage/"
PAPER = "paper/final/Kalshi-Mispricing-and-Arbitrage-Final-Paper.pdf"

VIEWS = [
    {"slug":"liquidity", "mode":"book", "title":"The Liquidity Behind the Quote",
     "short":"Order-book liquidity", "kind":"Recorded observations", "n":"01",
     "description":"Follow displayed ask-side depth through a short observation window, then compare the cost of different order sizes.",
     "detail":"Twenty REST observations reveal how much size is displayed at each ask. The companion graph sweeps the final recorded book, making the effect of order size visible.",
     "read":"Each 3D curve is a recorded observation. Price, elapsed collection time and cumulative contracts occupy the three axes. Change the contract to inspect a different book. The two-dimensional graph compares average acquisition cost with a raw-fee scenario; a missing point means insufficient displayed depth.",
     "limit":"The observations are from 17 October 2026, not current quotes. HTTP collection times are not exchange timestamps. Displayed liquidity does not establish a fill, queue position or an executable arbitrage. Python calculations additionally model fee rounding.",
     "notebook":"02_order_books_fees_and_liquidity.ipynb"},
    {"slug":"probability", "mode":"probability", "title":"Calibrating the Market’s Odds",
     "short":"Probability calibration", "kind":"Observed vectors / model scenarios", "n":"02",
     "description":"Change the temperature of a six-outcome probability vector and compare its shape with the market-derived baseline.",
     "detail":"A calibration temperature changes the concentration of market-derived probabilities. The surface shows this transformation for an observed event; the companion bars show the selected slice.",
     "read":"Choose a city-date event and move the temperature slider. T below one concentrates the probabilities; T above one flattens them. At T = 1 the original vector is retained. The star marks the subsequently observed winning outcome, which was used for scoring rather than forecast construction.",
     "limit":"The development candidate failed validation, so the selected research model remains T = 1. Moving the slider is a sensitivity exercise, not a new fitted forecast. These probabilities come from market quotes; the engine is not an independent weather forecasting model.",
     "notebook":"04_probability_modelling_and_selection.ipynb"},
    {"slug":"execution", "mode":"laboratory", "title":"When a Basket Fails to Fill",
     "short":"Arbitrage and execution risk", "kind":"Synthetic mechanism", "n":"03",
     "description":"Vary the basket discount, number of legs and fill probability to explore how incomplete execution can create losses.",
     "detail":"A complete basket can have a positive conditional payoff while partial fills remain risky. This analytical laboratory separates expected payoff from the probability of losing money.",
     "read":"Change the gross basket discount and the number of legs. The surface maps the probability of loss across discount and per-leg fill probability. The companion graph plots expected payoff and loss probability for the selected discount. Hover for precise scenario values.",
     "limit":"The model assumes equally likely outcomes, an exhaustive single-winner partition and independent fills. The fee coefficient is an illustrative raw 7% quadratic schedule. Settlement exceptions, queue priority, correlated fills, funding and later price moves are excluded. This is not an estimated trading return.",
     "notebook":"06_execution_risk_and_research_reflections.ipynb"},
]


def head(title, description, path, prefix, graph=False, mode=""):
    thumb = "probability-in-motion.jpg" if graph else "pricing-uncertainty.jpg"
    canonical = BASE + path
    esc = html.escape
    attrs = f' data-explorer="{mode}"' if mode else ""
    return f'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{esc(title)} | Joel Cerraga</title><meta name="description" content="{esc(description)}"><meta name="author" content="Joel Cerraga"><meta name="theme-color" content="#102b3e">
<link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:site_name" content="Prediction Market Research"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}assets/thumbnails/{thumb}"><meta property="og:image:secure_url" content="{BASE}assets/thumbnails/{thumb}"><meta property="og:image:type" content="image/jpeg"><meta property="og:image:width" content="1774"><meta property="og:image:height" content="887"><meta property="og:image:alt" content="{esc(title)} by Joel Cerraga: conceptual teal geometry on white">
<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{esc(title)}"><meta name="twitter:description" content="{esc(description)}"><meta name="twitter:image" content="{BASE}assets/thumbnails/{thumb}"><meta name="twitter:image:alt" content="{esc(title)} by Joel Cerraga">
<link rel="icon" type="image/svg+xml" href="{prefix}assets/favicon.svg"><link rel="stylesheet" href="{prefix}assets/site.css"><link rel="stylesheet" href="{prefix}assets/research.css?v=20261018.2"><script src="{prefix}assets/site.js" defer></script></head><body{attrs}><a class="skip-link" href="#main">Skip to content</a>
<header class="site-header"><div class="wrap nav-inner"><a class="brand" href="{prefix}index.html"><img class="brand-mark" src="{prefix}assets/favicon.svg" width="34" height="34" alt=""><span>Prediction Markets<small>Joel Cerraga</small></span></a><button class="nav-toggle" type="button" aria-controls="site-nav" aria-expanded="false">Menu</button><nav class="nav-links" id="site-nav" aria-label="Main navigation"><a href="{prefix}index.html" {'aria-current="page"' if not graph else ''}>Overview</a><a href="{prefix}explorers/" {'aria-current="page"' if graph else ''}>Interactive graphs</a><a href="{prefix}{PAPER}">Paper ↗</a><a href="{REPO}">GitHub ↗</a></nav></div></header><main id="main">'''


def footer(prefix):
    return f'''</main><footer class="site-footer"><div class="wrap footer-inner"><p>Joel Cerraga · Quantitative research · October 2026</p><div class="footer-links"><a href="{prefix}explorers/">Interactive graphs</a><a href="{prefix}{PAPER}">Final paper</a><a href="{REPO}">Source &amp; reproduction</a></div></div></footer></body></html>'''


def cards(prefix):
    return '<div class="card-grid three">' + ''.join(f'''<a class="graph-card" href="{prefix}explorers/{v['slug']}/"><div class="card-image"><img src="{prefix}assets/previews/{v['slug']}.svg" width="660" height="460" alt="Static scientific preview of {v['short'].lower()}" loading="lazy"><span class="card-tag">{v['kind']}</span></div><div class="card-body"><p class="card-meta">{v['n']} / Research explorer</p><h3>{v['title']}</h3><p>{v['description']}</p><div class="card-bottom"><span>Open explorer</span><span aria-hidden="true">↗</span></div></div></a>''' for v in VIEWS) + '</div>'


def landing():
    return head("Pricing Uncertainty", "A cost-aware Kalshi research engine by Joel Cerraga: probability modelling, market microstructure and conditional arbitrage screening.", "", "") + f'''
<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><p class="eyebrow">Probability modelling · Market microstructure · Arbitrage</p><h1>Pricing<br><span>Uncertainty</span></h1><p class="lede">When is a price discrepancy an opportunity? A Kalshi research engine that connects probability, displayed liquidity and contract payoffs before interpreting a trading edge.</p><div class="button-row"><a class="button" href="explorers/">Explore the graphs ↗</a><a class="button secondary" href="{PAPER}">Read the paper</a></div><p class="hero-note">Research by Joel Cerraga · Python · Public REST endpoints</p></div><figure class="hero-visual"><img src="assets/previews/liquidity.svg" width="660" height="460" alt="Recorded cumulative ask depth across observation times"><figcaption class="visual-label"><span>RECORDED ASK-SIDE DEPTH</span><span>17 OCT 2026</span></figcaption></figure></div></section>
<div class="wrap"><div class="stat-strip"><div class="stat"><strong>270</strong><span>historical city-date events</span></div><div class="stat"><strong>1,620</strong><span>binary outcome contracts</span></div><div class="stat"><strong>8</strong><span>executed research notebooks</span></div><div class="stat"><strong>3</strong><span>interactive 3D explorers</span></div></div></div>
<section class="section"><div class="wrap question-grid"><div><p class="eyebrow">The research question</p><h2>A discrepancy is only the starting point.</h2><p>A sum of quoted prices can look inconsistent while transaction costs, missing depth or the contract’s settlement rules remove the apparent opportunity. The engine makes each of these assumptions explicit.</p><p>As Hasbrouck (2007) explains in <em>Empirical market microstructure</em>, the trading process matters for interpreting observed prices. As Wolfers and Zitzewitz (2006) discuss, reading prediction-market prices as probabilities also requires assumptions about the market and its participants.</p></div><div class="method-list"><div class="method-item"><span class="method-num">01</span><div><h3>Reconstruct the tradable quote</h3><p>Convert complementary YES and NO bids into asks; retain fixed-point quantities; sweep the displayed depth and apply a stated fee model.</p></div></div><div class="method-item"><span class="method-num">02</span><div><h3>Audit the payoff states</h3><p>Check event membership, threshold relationships and settlement contingencies before screening baskets or statewise portfolios.</p></div></div><div class="method-item"><span class="method-num">03</span><div><h3>Validate the probability model</h3><p>Fit calibration on development dates, select on validation, then score the frozen choice on a later chronological sample.</p></div></div></div></div></section>
<section class="section tinted"><div class="wrap question-grid"><div><p class="eyebrow">Main findings / recorded sample</p><h2>The apparent gaps did not survive the cost test.</h2><p>Across 268 complete noon panels, 34 conditional historical basket checks had positive gross gaps. None remained positive under the stated current-fee scenario. Historical candles provide no executable depth or fill evidence.</p><p>The development calibration candidate also failed validation. The selected model retained the unchanged market-derived baseline; the later sample supplies no evidence of profitable model-based trading.</p></div><div class="result-box"><h3>From gross discrepancy to net payoff</h3><p class="muted small">536 historical basket-side checks · integer-resolution scenario</p><div class="result-numbers"><div class="result-number"><strong>34</strong><span>Positive gross gaps<br>5 YES baskets + 29 NO baskets</span></div><div class="result-number"><strong>0</strong><span>Positive after fees<br>Current direct-member scenario</span></div></div><p class="result-note">The short live pilot also found no positive cost-adjusted candidate. These observations are sample-specific and do not establish universal market efficiency or realised returns.</p><a class="text-link" href="{PAPER}">Read the complete findings ↗</a></div></div></section>
<section class="section"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Interactive research</p><h2>Inspect the mechanics behind the result.</h2></div><p>Rotate a surface, inspect an order book and change a controlled execution mechanism.</p></div>{cards('')}<p class="graph-hint">The liquidity view uses recorded books. Calibration combines observed vectors with parameter scenarios. The execution laboratory is synthetic.</p></div></section>
<section class="section tinted"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Read. Inspect. Reproduce.</p><h2>The research record.</h2></div></div><div class="resource-grid"><article class="resource"><h3>The final paper</h3><p>39 A4 pages with complete front matter, 18 numbered equations, research reflections and Harvard references.</p><a href="{PAPER}">Open the PDF ↗</a></article><article class="resource"><h3>Code and notebooks</h3><p>Python modules, eight recorded notebooks, 45 analytical tests and six known-truth synthetic mechanisms.</p><a href="notebooks/">Browse the notebooks ↗</a></article><article class="resource"><h3>Decisions and limitations</h3><p>Rejected calibration, incomplete payoff assumptions, acquisition setbacks and the limits of recorded liquidity.</p><a href="{REPO}/blob/main/docs/research-reflections.md">Read the reflection log ↗</a></article></div><div class="callout" style="margin-top:35px"><p><strong>Scope of the evidence.</strong> The historical study covers daily maximum-temperature markets in New York, Chicago and Miami, 19 July–16 October 2026. Chronological splits are retrospective. The live observation session lasted about three minutes. The software submits no orders, and no reported finding is a realised trading return.</p></div></div></section>
<section class="section"><div class="wrap references"><h2>References</h2><p>Hasbrouck, J. (2007) <em>Empirical market microstructure: The institutions, economics, and econometrics of securities trading.</em> New York: Oxford University Press.</p><p>Wolfers, J. and Zitzewitz, E. (2006) <em>Interpreting prediction market prices as probabilities.</em> NBER Working Paper No. 12200. Cambridge, MA: National Bureau of Economic Research.</p><p><a href="references/harvard-references.txt">Complete Harvard bibliography ↗</a></p></div></section>''' + footer("")


def catalogue():
    return head("Probability in Motion", "Three interactive 3D research explorers: displayed liquidity, probability calibration and synthetic basket execution risk.", "explorers/", "../", True) + f'''
<section class="page-intro"><div class="wrap"><p class="breadcrumb"><a href="../index.html">Overview</a><span>/</span>Interactive graphs</p><div class="catalog-intro"><div><p class="eyebrow">Three perspectives on prediction markets</p><h1>Probability<br><span class="teal">in Motion</span></h1><p class="lede">Explore how a quoted probability becomes an acquisition cost, and how execution changes the payoff.</p><div class="tag-row"><span class="tag">Rotate and zoom</span><span class="tag">Linked 2D views</span><span class="tag">Download plotted values</span></div></div><img src="../assets/thumbnails/probability-in-motion.jpg" width="1774" height="887" alt="Probability in Motion: conceptual artwork for the research explorer collection"></div></div></section>
<section class="section"><div class="wrap">{cards('../')}<div class="callout" style="margin-top:30px"><p>Start with liquidity to see what the quotes actually display. Use calibration to examine a model transformation. Then open the execution laboratory to separate a complete-basket payoff from partial-fill risk. Each page identifies the evidence and the assumptions behind its graph.</p></div></div></section>''' + footer("../")


def controls():
    return '''<div class="controls"><label class="control" id="ticker-control">Recorded contract<select id="ticker"></select></label><label class="control" id="event-control" hidden>Historical noon event<select id="event"></select></label><label class="control" id="temperature-control" hidden>Calibration temperature: <span id="temperature-value">1.00</span><input id="temperature" type="range" min="0.25" max="4" step="0.05" value="1"></label><label class="control" id="discount-control" hidden>Gross basket discount: <span id="discount-value">10%</span><input id="discount" type="range" min="0" max="0.15" step="0.005" value="0.1"></label><label class="control" id="legs-control" hidden>Number of legs<select id="legs"><option>2</option><option>3</option><option>4</option><option selected>6</option><option>8</option></select></label></div>'''


def explorer(v):
    prefix="../../"
    nextv=VIEWS[(VIEWS.index(v)+1)%len(VIEWS)]
    return head(v['title'],v['description'],f"explorers/{v['slug']}/",prefix,True,v['mode']) + f'''
<section class="page-intro"><div class="wrap"><p class="breadcrumb"><a href="../../index.html">Overview</a><span>/</span><a href="../">Interactive graphs</a><span>/</span>{v['short']}</p><p class="eyebrow">{v['n']} / {v['kind']}</p><h1>{v['title']}</h1><p class="lede">{v['detail']}</p></div></section>
<section class="section explorer-section"><div class="wrap"><div class="viewer"><div class="viewer-toolbar"><strong>{v['short']}</strong><a href="../../{PAPER}">Research paper ↗</a></div><div class="preview-stage" id="preview-stage"><img src="../../assets/previews/{v['slug']}.svg" width="660" height="460" alt="Static scientific preview of {v['short'].lower()}"><button type="button" class="button" id="load-interactive" data-prefix="../../">Load interactive graph ↗</button><p>Drag to rotate · Scroll to zoom · Hover to inspect. A 2D companion supports reading the same scenario.</p></div><p class="loading-status" id="interactive-status" role="status" aria-live="polite"></p><div id="interactive-panel" class="interactive-panel" hidden>{controls()}<div class="stats" id="stats" aria-live="polite"></div><div class="plot-grid"><section class="plot-card"><div id="plot3d" class="plot" role="img" aria-label="Interactive three-dimensional research plot"></div><p class="caption" id="caption3d"></p></section><section class="plot-card"><div id="plot2d" class="plot" role="img" aria-label="Two-dimensional companion plot"></div><p class="caption" id="caption2d"></p></section></div><div class="note" id="note"></div><div class="tools"><button id="reset" type="button" class="button secondary">Reset view</button><button id="download" type="button" class="button secondary">Download plotted data (CSV)</button></div></div></div>
<div class="read-grid"><section><h2>How to read it</h2><p>{v['read']}</p><div class="detail-links"><a href="../../notebooks/{v['notebook']}">Download the notebook</a><a href="{REPO}/blob/main/notebooks/{v['notebook']}">View notebook on GitHub ↗</a></div></section><section><h2>Interpretation and limits</h2><p>{v['limit']}</p></section></div><div class="next-explorer"><a href="../">← All explorers</a><a href="../{nextv['slug']}/">{nextv['short']} →</a></div></div></section><script src="../../assets/load-explorer.js?v=20261018.2" defer></script>''' + footer(prefix)


def notebooks():
    ms=json.loads((ROOT/'protocol/milestones.json').read_text())
    rows=''.join(f'''<tr><td>{m['id']}</td><td><a href="{Path(m['notebook']).name}">{html.escape(m['title'].split(' · ',1)[1])}</a></td><td>{m['executed_code_cells']}</td><td><a href="{REPO}/blob/main/{m['notebook']}">View ↗</a></td></tr>''' for m in ms)
    return head("From Quotes to Evidence", "Eight research notebooks covering data provenance, order books, payoff constraints, probability modelling and execution risk.", "notebooks/", "../") + f'''<section class="page-intro"><div class="wrap narrow"><p class="breadcrumb"><a href="../index.html">Overview</a><span>/</span>Research notebooks</p><p class="eyebrow">Eight milestones / 31 executed code cells</p><h1>From Quotes to Evidence</h1><p class="lede">Follow the research in the order it was developed. Each notebook retains its recorded outputs, equations and interpretation.</p></div></section><section class="section"><div class="wrap"><div class="table-scroll"><table class="notebook-table"><thead><tr><th>Milestone</th><th>Notebook download</th><th>Code cells</th><th>GitHub</th></tr></thead><tbody>{rows}</tbody></table></div><div class="callout" style="margin-top:28px"><p>The empirical notebooks require the separately retained input snapshot for an exact rerun. The repository’s offline reproduction command runs the analytical tests and synthetic experiments with no API connection. Recorded outputs are not represented as a newly executed public-data backtest.</p></div><div class="button-row"><a class="button" href="../{PAPER}">Read the paper</a><a class="button secondary" href="{REPO}#reproduce-the-software-and-synthetic-experiments">Reproduction instructions ↗</a></div></div></section>''' + footer('../')


def main():
    pages={"index.html":landing(),"explorers/index.html":catalogue(),"notebooks/index.html":notebooks()}
    pages.update({f"explorers/{v['slug']}/index.html":explorer(v) for v in VIEWS})
    for path,text in pages.items():
        dest=ROOT/path;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(text)
    print(f"Built {len(pages)} static pages.")


if __name__ == '__main__':
    main()
